function test_pll_run_tools()
% Generated by GitHub Copilot under Lance Lascari's direction.
% Offline tests; all outputs and GUI state are isolated in a temporary folder.
tool_directory=fileparts(mfilename('fullpath'));
path_before=path;
directory_before=pwd;
visibility_before=get(0,'defaultfigurevisible');
temporary=tempname();
mkdir(temporary);
cleanup=onCleanup(@() cleanup_test(temporary,path_before,directory_before,visibility_before));
addpath(tool_directory,fullfile(tool_directory,'..','pn'));
set(0,'defaultfigurevisible','off');
if exist('OCTAVE_VERSION','builtin')
    graphics_toolkit('qt');
end
[config,groups]=rfdude_pll_configuration();
assert(numel(fieldnames(config.pll_inputs_s))==sum(cellfun(@numel,groups(:,2))));
assert(config.run_options_s.bOverwriteResults);
assert(isequal(rfdude_pll_parse_value('[1000 2000 4000]'),[1000 2000 4000]));
assert(isequal(rfdude_pll_parse_value('4:-1:2'),[4 3 2]));
assert(isequal(rfdude_pll_parse_value('-Inf Inf'),[-Inf Inf]));
must_fail(@() rfdude_pll_parse_value('system(''touch BAD'')'));
must_fail(@() rfdude_pll_parse_value('1:0:3'));
must_fail(@() rfdude_pll_parse_value('1:1:100001'));
config.pll_inputs_s.bSaveFigs=0;
config.pll_inputs_s.bWriteCSVtable=0;
config.pll_inputs_s.bDoTransient=0;
config.pll_inputs_s.bDoTransientNonlinear=0;
config.pll_inputs_s.fsweep_main_pts=101;
config.pll_inputs_s.def_filename='_single.mat';
config.run_options_s.bShowCorePlots=false;
config.run_options_s.bEnableDataViewer=false;
config.run_options_s.base_directory=temporary;
rfdude_pll_validate_configuration(config,temporary);

% Compare wrapper output to the unwrapped historical analysis and integrations.
baseline=direct_baseline(config,temporary);
sentinel=figure('visible','off','name','Existing figure must survive');
sentinel_line=plot(1:3,[4 5 6]);
single=rfdude_pll_run(config.pll_inputs_s,config.run_options_s);
assert(ishghandle(sentinel) && ishghandle(sentinel_line));
assert(strcmp(pwd,directory_before));
assert(strcmp(get(0,'defaultfigurevisible'),'off'));
assert(numel(single.cases)==1 && single.completed(1));
assert(max(abs(single.cases{1}.pn_struct.n-baseline.n))<1e-10);
assert(abs(single.cases{1}.integrated_noise_rad-baseline.integrated_noise_rad)<1e-12);
assert(abs(single.cases{1}.residual_FM_Hz-baseline.residual_FM_Hz)<1e-10);
assert(strcmp(single.cases{1}.small_signal.status,'disabled'));
assert(isnan(single.cases{1}.small_signal.settling_time_s));
assert(exist(fullfile(temporary,'_single_cases','_single_case0001.mat'),'file')==2);
assert(exist(fullfile(temporary,'_single_data.mat'),'file')==2);
protected_options=config.run_options_s;
protected_options.bOverwriteResults=false;
must_fail(@() rfdude_pll_run(config.pll_inputs_s,protected_options));
overwritten=rfdude_pll_run(config.pll_inputs_s,config.run_options_s);
assert(overwritten.completed(1));
close(sentinel);

% Fixed third pole, resynthesis at each bandwidth, and both transient traces.
config.pll_inputs_s.def_filename='_sweep.mat';
config.pll_inputs_s.filter_override_3rdpole_only=1;
config.pll_inputs_s.RR3=baseline.components.R3;
config.pll_inputs_s.CC3=baseline.components.C3;
config.pll_inputs_s.bDoTransient=1;
config.pll_inputs_s.bDoTransientNonlinear=1;
config.pll_inputs_s.transient_delta_f_Hz=5000;
config.pll_inputs_s.transient_tmax_s=.001;
config.pll_inputs_s.transient_points=301;
config.pll_inputs_s.transient_nl_steps_per_ref=10;
config.run_options_s.bRunSweep=true;
config.run_options_s.sweep_values=[1000 2000 4000];
sweep=rfdude_pll_run(config.pll_inputs_s,config.run_options_s);
assert(all(sweep.completed));
assert(numel(sweep.cases)==3);
for k=1:3
    c=sweep.cases{k};
    assert(c.components.R3==config.pll_inputs_s.RR3);
    assert(c.components.C3==config.pll_inputs_s.CC3);
    assert(c.requested_inputs.BW_desired_Hz==sweep.values(k));
    assert(numel(c.noise_at_offsets_dBc_Hz)==4);
    assert(numel(c.small_signal.time_s)==301);
    expected_steps=ceil(config.pll_inputs_s.transient_tmax_s/ ...
        (1/(config.pll_inputs_s.Fref_Hz*config.pll_inputs_s.transient_nl_steps_per_ref)));
    assert(numel(c.nonlinear.time_s)==expected_steps+1);
    assert(any(strcmp(c.small_signal.status,{'settled','not_settled'})));
    assert(any(strcmp(c.nonlinear.status,{'settled','not_settled'})));
end
assert(sweep.cases{1}.components.C1~=sweep.cases{3}.components.C1);
assert(max(abs(sweep.cases{1}.pn_struct.n-sweep.cases{3}.pn_struct.n))>1);
% File drivers are explicit: exporting must never use MATLAB's default printer.
export_config=config;
export_config.run_options_s.bRunSweep=false;
export_config.pll_inputs_s.def_filename='_export.mat';
export_config.pll_inputs_s.bSaveFigs=1;
export_config.pll_inputs_s.bSaveFigsPDF=1;
export_config.pll_inputs_s.bSaveFigsJPG=1;
export_data=rfdude_pll_run(export_config.pll_inputs_s,export_config.run_options_s);
assert(export_data.completed(1));
for suffix={'_transient','_transient_nl','_VCO','_R2_R3Noise','_totals','_contribs_total'}
    filename=fullfile(temporary,'_export_cases',['_export_case0001' suffix{1}]);
    fid=fopen([filename '.pdf'],'rb');
    assert(fid>=0,'Missing PDF export');
    signature=fread(fid,5,'*char').';
    fclose(fid);
    assert(strcmp(signature,'%PDF-'),'Export must be a real PDF file');
    image=imfinfo([filename '.jpg']);
    assert(strcmpi(image.Format,'jpg') || strcmpi(image.Format,'jpeg'));
    assert(image.Width>0 && image.Height>0);
end
short_config=config;
short_config.run_options_s.bRunSweep=false;
short_config.run_options_s.bEnableDataViewer=true;
short_config.pll_inputs_s.def_filename='_short_transient.mat';
short_config.pll_inputs_s.transient_tmax_s=1e-6;
short_config.pll_inputs_s.transient_points=3;
short_data=rfdude_pll_run(short_config.pll_inputs_s,short_config.run_options_s);
assert(strcmp(short_data.cases{1}.small_signal.status,'not_settled'));
assert(strcmp(short_data.cases{1}.nonlinear.status,'not_settled'));
assert(isnan(short_data.cases{1}.small_signal.settling_time_s));
assert(isnan(short_data.cases{1}.nonlinear.settling_time_s));
automatic_viewer=findall(0,'tag','pll_data_viewer');
assert(numel(automatic_viewer)==1);
close(automatic_viewer);
invalid=config;
invalid.pll_inputs_s.filter_override=1;
must_fail(@() rfdude_pll_validate_configuration(invalid,temporary));
invalid=config;
invalid.run_options_s.sweep_values=[2000 2000];
must_fail(@() rfdude_pll_validate_configuration(invalid,temporary));

% Generated scripts run from their own directory, without hardcoded tool paths.
config.run_options_s.bRunSweep=false;
config.pll_inputs_s.bDoTransient=0;
config.pll_inputs_s.bDoTransientNonlinear=0;
config.pll_inputs_s.def_filename='_generated.mat';
filename=fullfile(temporary,'aa_run_user_config_test_single.m');
rfdude_pll_generate_script(config,filename);
source=fileread(filename);
assert(~isempty(strfind(source,'Generated by GitHub Copilot under Lance Lascari')));
assert(~isempty(strfind(source,'pll_inputs_s.CC3=')));
assert(~isempty(strfind(source,'run_options_s.bOverwriteResults=1;')));
source_lines=regexp(source,'\r\n|\n','split');
assignment_count=0;
for k=2:numel(source_lines)
    if ~isempty(regexp(source_lines{k},'^(pll_inputs_s|run_options_s)\.\w+=','once')) && ...
            isempty(strfind(source_lines{k},'base_directory'))
        assert(strncmp(source_lines{k-1},'% ',2), ...
            'Each generated editable setting must have a nearby explanation');
        assignment_count=assignment_count+1;
    end
end
assert(assignment_count==numel(fieldnames(config.pll_inputs_s))+ ...
    numel(fieldnames(config.run_options_s))-1);
assert(~isempty(strfind(source,'%% optional small-signal frequency-step response')));
assert(~isempty(strfind(source,'not guaranteed achieved crossover')));
assert(~isempty(strfind(source,'GNU Octave first')));
assert(isempty(strfind(source,'all characteristics of the source/pn_struct will override')));
assert(isempty(strfind(source,['''' tool_directory ''''])));
must_fail(@() rfdude_pll_generate_script(config,filename));
execute_script(filename);
assert(exist(fullfile(temporary,'_generated_data.mat'),'file')==2);
config.run_options_s.bRunSweep=true;
config.pll_inputs_s.def_filename='_generated_sweep.mat';
filename=fullfile(temporary,'aa_run_user_config_test_sweep.m');
rfdude_pll_generate_script(config,filename);
execute_script(filename);
saved=load(fullfile(temporary,'_generated_sweep_data.mat'),'pll_data_s');
assert(all(saved.pll_data_s.completed) && numel(saved.pll_data_s.cases)==3);

% File-backed noise is embedded so browsing survives removal of source files.
file_config=config;
file_config.run_options_s.bRunSweep=false;
file_config.run_options_s.bShowCorePlots=true;
file_config.pll_inputs_s.def_filename='_file_noise.mat';
file_config.pll_inputs_s.pn_ylimits=[-180 -20];
file_config.pll_inputs_s.bUseVCOFromFile=1;
file_config.pll_inputs_s.bUseTCXOFromFile=1;
file_config.pll_inputs_s.FileVCO='vco.mat';
file_config.pll_inputs_s.FileTCXO='ref.mat';
pn_struct=struct('fc',445e6,'f',[100 1000 10000 100000], ...
    'n',[-70 -90 -110 -130],'kvco',10e6,'name','Test VCO', ...
    'comment','Synthetic test data','clock',clock);
options='This unrelated MAT variable must not overwrite the run workspace';
save(fullfile(temporary,'vco.mat'),'pn_struct','options','-v7');
pn_struct.fc=16e6;
pn_struct.name='Test reference';
save(fullfile(temporary,'ref.mat'),'pn_struct','-v7');
file_data=rfdude_pll_run(file_config.pll_inputs_s,file_config.run_options_s);
assert(isequal(get(gca,'ylim'),[-180 -20]));
close all;
assert(file_data.cases{1}.Kvco_Hz_volt==10e6);
assert(file_data.cases{1}.effective_inputs.Kvco_Hz_volt==10e6);
assert(isfield(file_data.cases{1}.source_noise,'VCO'));
assert(isfield(file_data.cases{1}.source_noise,'TCXO'));
delete(fullfile(temporary,'vco.mat'));
delete(fullfile(temporary,'ref.mat'));
viewer=cc_pll_data_viewer(file_data.dataset_path);
close(viewer);

% Reopen saved datasets and render every view, including transient contours.
viewer=cc_pll_data_viewer(sweep.dataset_path);
choice=findobj(viewer,'tag','pll_view_kind');
points=findobj(viewer,'tag','pll_view_points');
point_label=findobj(viewer,'tag','pll_view_points_label');
for mode=1:numel(get(choice,'string'))
    set(choice,'value',mode);
    callback=get(choice,'callback');
    callback(choice,[]);
    status=findobj(viewer,'tag','pll_view_status');
    assert(isempty(strfind(get(status,'string'),'Plot failed:')));
    if any(mode==[3 18 19])
        assert(get(points,'max')>1);
        assert(~isempty(strfind(get(point_label,'string'),'Ctrl for overlays')));
    else
        assert(get(points,'max')==1);
        assert(~isempty(strfind(get(point_label,'string'),'plot shows all')));
    end
    if any(mode==[1 2 14 15 16 17])
        assert(~isempty(strfind(get(status,'string'),'Drag within the plot to rotate')));
        assert(strcmp(get(findobj(viewer,'tag','pll_camera_front'),'enable'),'on'));
    else
        assert(strcmp(get(findobj(viewer,'tag','pll_camera_front'),'enable'),'off'));
    end
end
set(choice,'value',1);
callback=get(choice,'callback');
callback(choice,[]);
axes_handle=findobj(viewer,'tag','pll_view_axes');
camera=findobj(viewer,'tag','pll_camera_front');
callback=get(camera,'callback');
callback(camera,[]);
assert(isequal(get(axes_handle,'view'),[0 0]));
camera=findobj(viewer,'tag','pll_camera_2d');
callback=get(camera,'callback');
callback(camera,[]);
assert(isequal(get(axes_handle,'view'),[0 90]));
camera=findobj(viewer,'tag','pll_camera_iso');
callback=get(camera,'callback');
callback(camera,[]);
assert(~isempty(strfind(get(findobj(viewer,'tag','pll_view_status'),'string'),'Fixed camera view: Iso')));
set(points,'value',[1 3]);
set(choice,'value',3);
callback=get(points,'callback');
callback(points,[]);
assert(numel(findobj(viewer,'type','line'))>=2);
set(choice,'value',1);
callback=get(choice,'callback');
callback(choice,[]);
assert(get(points,'max')==1 && numel(get(points,'value'))==1);
close(viewer);
viewer=cc_pll_data_viewer(single.dataset_path);
close(viewer);
failed=sweep;
failed.completed(2)=false;
failed.cases{2}=struct('status','failed','message','Test failure', ...
    'requested_inputs',sweep.cases{2}.requested_inputs);
viewer=cc_pll_data_viewer(failed);
close(viewer);
pn_struct=struct();
legacy_file=fullfile(temporary,'legacy_core_output.mat');
save(legacy_file,'pn_struct','-v7');
rejected=false;
try
    cc_pll_data_viewer(legacy_file);
catch err
    rejected=~isempty(strfind(err.message,'<basename>_data.mat')) && ...
        ~isempty(strfind(err.message,'*_caseNNNN.mat'));
end
assert(rejected,'Legacy core MAT files should explain which dataset to open');

% GUI navigation preserves unfinished values; saved state restores them.
state_file=fullfile(temporary,'_last_setup.mat');
gui=bb_pll_setup_gui(state_file);
assert(get(findobj(gui,'tag','o_bOverwriteResults'),'value')==1);
edit=findobj(gui,'tag','p_BW_desired_Hz');
set(edit,'string','unfinished entry');
callback=get(edit,'callback');
callback(edit,[]);
sections=findobj(gui,'tag','pll_setup_section');
set(sections,'value',4);
callback=get(sections,'callback');
callback(sections,[]);
assert(strcmp(get(edit,'string'),'unfinished entry'));
set(findobj(gui,'tag','pll_run_script'),'value',1);
close(gui);
gui=bb_pll_setup_gui(state_file);
assert(strcmp(get(findobj(gui,'tag','p_BW_desired_Hz'),'string'),'unfinished entry'));
assert(get(findobj(gui,'tag','pll_setup_section'),'value')==4);
assert(get(findobj(gui,'tag','pll_run_script'),'value')==1);
assert(strcmp(get(findobj(gui,'tag','p_CC1'),'enable'),'off'));
assert(ishghandle(findobj(gui,'tag','pll_reset')));
delete(gui);
fprintf('\nPASS: defaults, validation, numerical baseline, single/sweep generation, saved datasets, all viewer modes, and GUI persistence\n');
end

function result=direct_baseline(config,directory)
directory_before=pwd;
cleanup=onCleanup(@() cd(directory_before));
cd(directory);
pll_inputs_s=config.pll_inputs_s;
pll_inputs_s.def_filename='_baseline.mat';
rfdude_pll_oct_0p1;
result=struct('n',pn_struct.n,'components',struct('C1',C1,'C2',C2,'R2',R2,'C3',C3,'R3',R3));
x=logspace(log10(pn_struct.f(1)),log10(pn_struct.f(end)), ...
    1+50*(log10(pn_struct.f(end))-log10(pn_struct.f(1))));
noise=interp1(log10(pn_struct.f),pn_struct.n,log10(x));
result.integrated_noise_rad=integrate_ssb_pnoise(x,noise, ...
    config.run_options_s.integration_lower_Hz,config.run_options_s.integration_upper_Hz);
result.residual_FM_Hz=calculate_residual_fm(x,noise, ...
    config.run_options_s.integration_lower_Hz,config.run_options_s.integration_upper_Hz);
close all;
end

function must_fail(action)
failed=false;
try
    action();
catch
    failed=true;
end
assert(failed,'Expected an explicit error');
end

function execute_script(filename)
run(filename);
if ~run_options_s.bRunSweep
    assert(isequal(pn_struct,PLL_DATA_s.cases{1}.pn_struct));
    assert(int_noise==PLL_DATA_s.cases{1}.integrated_noise_rad);
end
end

function cleanup_test(directory,old_path,old_directory,visibility)
close all;
cd(old_directory);
path(old_path);
set(0,'defaultfigurevisible',visibility);
rmdir(directory,'s');
end
